requirements.referenceSolution:
function login($pdo, $username, $password) {
    $stmt = $pdo->prepare('SELECT * FROM users WHERE username = ?');
    $stmt->execute([$username]);
    $row = $stmt->fetch();
    if ($row === false) {
        return false;
    }
    return password_verify($password, $row['password']);
}

