class FakeStmt {
    public array $rows = [];
    public array $params = [];
    public function __construct(public array $table, public string $sql) {}
    public function bindValue($k, $v): FakeStmt { $this->params[$k] = $v; return $this; }
    public function bindParam($k, &$v): FakeStmt { $this->params[$k] = $v; return $this; }
    public function execute($params = []): bool {
        foreach ($params as $k => $v) { $this->params[$k] = $v; }
        $uname = reset($this->params);
        $this->rows = [];
        foreach ($this->table as $row) {
            if ($row['username'] === $uname) { $this->rows = [$row]; break; }
        }
        return true;
    }
    public function fetch() { return $this->rows[0] ?? false; }
}

class FakePDO {
    public function __construct(public array $table) {}
    public function query(string $sql): FakeStmt {
        $s = new FakeStmt($this->table, $sql);
        if (preg_match("/'\s*or\s*'/i", $sql)) {
            // 裸拼接 SQL：' OR ' 使 WHERE 恒真 → 命中第一行（模拟注入绕过）
            $s->rows = [$this->table[0]];
        } elseif (preg_match("/'\s*--/", $sql)) {
            // 注释截断：-- 后密码子句失效 → 仅按用户名字面量命中
            foreach ($this->table as $row) {
                if (strpos($sql, "'" . $row['username'] . "'") !== false) { $s->rows = [$row]; break; }
            }
        } else {
            // 字面量匹配：SQL 里同时出现 '用户名' 与 '明文口令' 才命中（表内实际存哈希）
            foreach ($this->table as $row) {
                if (strpos($sql, "'" . $row['username'] . "'") !== false && strpos($sql, "'" . $row['plain'] . "'") !== false) {
                    $s->rows = [$row];
                }
            }
        }
        return $s;
    }
    public function prepare(string $sql): FakeStmt { return new FakeStmt($this->table, $sql); }
}

function makePdo(): FakePDO {
    return new FakePDO([[
        'username' => 'admin',
        'plain' => 's3cret',
        'password' => password_hash('s3cret', PASSWORD_DEFAULT),
    ]]);
}

